import React from 'react';
import './BookCard.css';
import { useBookContext } from '../../../context/BookContext';


function BookCard({ title, imgSrc, description }) {
  return (
    <div className="book-card">
      <img src={imgSrc} alt={title} className="book-image" />
      <h3 className="book-title">{title}</h3>
      <h4 className="book-price">{price}</h4>
      <h5 className="book-genre">{genre}</h5>
      <h6 className="book-pages">{pages}</h6>
      <p className="book-description">{description}</p>
      <button className="book-detail-button">Переглянути більше</button>
    </div>
  );
}

export default BookCard;
